<script lang="ts">
 import {onMount,tick,untrack} from 'svelte';
 import {hashReaderState} from './readerState';
 import ActionInput from './ActionInput.svelte';
 interface Props {connected?:boolean;deliveryPending?:boolean;recoveredAction?:any;sessionId?:string;campaignId?:string;title?:string;worldOpen?:boolean;onworld?:()=>void;transcriptControls?:any[];onreaderedit?:(payload:any)=>Promise<any>;campaign?:any;records?:any[];runs?:any[];run?:any;busy?:boolean;onturn?:(action:{text:string;actionType:string})=>Promise<void>;onstop?:()=>Promise<void>;onresume?:()=>Promise<void>;oninspect?:(id:string)=>void;onanswer?:(answer:string)=>Promise<void>;ondismiss?:()=>Promise<void>;}
 let {connected=true,deliveryPending=false,recoveredAction=null,sessionId='browser_default',campaignId='synthetic',title='Your story',worldOpen=false,onworld,transcriptControls=[],onreaderedit,campaign=null,records=[],runs=[],run=null,busy=false,onturn,onstop,onresume,oninspect,onanswer,ondismiss}:Props=$props();
 const pov=$derived(records.find(record=>record.id===campaign?.activePovId)),player=$derived(records.find(record=>record.id===campaign?.playerId)),scene=$derived(records.find(record=>record.id===campaign?.sceneLocationId));
 let editing=$state(''),draft=$state(''),customAnswer=$state(''),conversation=$state<HTMLDivElement>(),nearBottom=$state(true);
 const control=(id:string)=>transcriptControls.find(c=>c.runId===id);
 async function reader(turn:any,hidden:boolean,text:string|null){const current=control(turn.id);await onreaderedit?.({runId:turn.id,expectedHash:await hashReaderState({hidden:current?.hidden||false,text:current?.text??null}),hidden,text});editing='';}
 const turns=$derived([...runs.filter(r=>r.request?.action==='story'&&r.id!==run?.id),...(run?.request?.action==='story'?[run]:[])].sort((a,b)=>a.at.localeCompare(b.at)));
 const signature=$derived(turns.map(t=>[t.id,t.status,t.text,t.streamingText,t.pendingQuestion?.answer].join(':')).join('|'));
 const pending=$derived(!!run?.pendingQuestion&&!run.pendingQuestion.answer&&!run.pendingQuestion.cancelled);
 $effect(()=>{signature;const follow=untrack(()=>nearBottom);void tick().then(()=>{if(follow&&conversation)conversation.scrollTop=conversation.scrollHeight;});});
 onMount(()=>{const observer=new ResizeObserver(()=>{if(nearBottom&&conversation)conversation.scrollTop=conversation.scrollHeight;});if(conversation)observer.observe(conversation);return()=>observer.disconnect();});
 function trackScroll(){if(conversation)nearBottom=conversation.scrollHeight-conversation.scrollTop-conversation.clientHeight<100;}
 async function respond(answer:string){await onanswer?.(answer);customAnswer='';nearBottom=true;}
</script>
<div class="story-reader" aria-label="Campaign story">
 <div class="conversation-header"><div><small>STORY</small><h1>{title}</h1><p>{scene?.name||'Choose a scene'} · Viewpoint: {pov?.name||'Choose a viewpoint'}</p></div><button class="world-toggle" aria-expanded={worldOpen} onclick={onworld}>World panel</button></div>
 <div class="conversation" role="log" aria-label="Story conversation" aria-live="polite" aria-relevant="additions text" aria-atomic="false" bind:this={conversation} onscroll={trackScroll}>
  {#if !turns.length}<div class="welcome"><span class="welcome-sigil">H</span><h2>Where does your story begin?</h2><p>Take an action, speak in character, or give the GM a direction.</p><div class="sources">{#if player}<button onclick={()=>oninspect?.(player.id)}>{player.name}</button>{/if}{#if scene}<button onclick={()=>oninspect?.(scene.id)}>{scene.name}</button>{/if}</div></div>{/if}
  {#each turns as turn (turn.id)}
   <article data-turn-id={turn.id} aria-label="Story turn">
    {#if !control(turn.id)?.hidden}
     <div class="message player-message"><div class="message-meta"><strong>You</strong><span>{turn.request.actionType||'Do'}</span>{#if ['think','ooc'].includes(turn.request.actionType)}<small>Private</small>{/if}</div><p class="player">{turn.request.text}</p></div>
     {#if turn.pendingQuestion?.answer}<div class="message gm-question"><div class="message-meta"><span class="gm-mark">H</span><strong>Game Master</strong></div><p class="turn-note">{turn.pendingQuestion.text}</p></div><div class="message answer-message"><div class="message-meta"><strong>Your answer</strong></div><p>{turn.pendingQuestion.answer}</p></div>{/if}
     <div class="message gm-message"><div class="message-meta"><span class="gm-mark">H</span><strong>Game Master</strong>{#if turn.status==='running'}<span class="working">● Working</span>{:else if turn.status==='paused'}<span>{turn.pendingQuestion&&!turn.pendingQuestion.answer?'Waiting for you':'Paused'}</span>{:else if turn.status==='failed'||turn.status==='cancelled'}<span>{turn.status}</span>{/if}</div>
      {#if turn.status==='completed'}<p class="narration">{control(turn.id)?.text??turn.text}</p>
      {:else if turn.streamingText}<p class="narration draft-narration">{turn.streamingText}</p><small class="draft-note">Draft; the turn has not completed.</small>
      {:else if turn.status==='running'}<div class="thinking" role="status"><span></span><span></span><span></span><p>{turn.activity?.findLast((entry:any)=>entry.kind==='tool')?.name?.replaceAll('_',' ')||'Considering the scene'}</p></div>
      {:else if turn.status==='paused'&&!turn.pendingQuestion}<p class="turn-note">The turn is paused. Resume when you are ready.</p>
      {:else if turn.status==='cancelled'}<p class="turn-note">This turn was dismissed.</p>{/if}
      {#if turn.error}<p class="turn-note">The turn could not complete. Your action is saved.</p><details class="turn-error-details"><summary>Error details</summary><p class="turn-error">{turn.error}</p></details>{/if}
      {#if turn.pendingQuestion&&!turn.pendingQuestion.answer&&!turn.pendingQuestion.cancelled}
       <div class="question-card" aria-label="GM question"><h2>{turn.pendingQuestion.text}</h2><div class="answer-choices">{#each turn.pendingQuestion.options as choice}<button disabled={busy||turn.status==='running'||turn.id!==run?.id} onclick={()=>respond(choice)}>{choice}</button>{/each}</div><label for="custom-answer">Your answer</label><div class="custom-answer"><input id="custom-answer" bind:value={customAnswer} maxlength="2000" placeholder="Or write your own answer"/><button disabled={busy||!customAnswer.trim()||turn.status==='running'||turn.id!==run?.id} onclick={()=>respond(customAnswer)}>Submit custom answer</button></div><button class="dismiss" disabled={busy||turn.status==='running'||turn.id!==run?.id} onclick={ondismiss}>Dismiss question</button></div>
      {/if}
      {#if turn.roll}<div class="roll-card">d{turn.roll.sides} <strong>{turn.roll.value}</strong><span>{turn.roll.purpose}</span></div>{/if}
      {#if turn.status==='completed'}<div class="sources">{#if turn.acceptedEventId}<button onclick={()=>oninspect?.(turn.acceptedEventId)}>Source account</button>{/if}<details class="reader-controls"><summary>Reader text controls</summary><p>Display edits preserve accepted source history.</p><button onclick={()=>{editing=turn.id;draft=control(turn.id)?.text??turn.text;}}>Edit reader text</button><button onclick={()=>reader(turn,true,control(turn.id)?.text??null)}>Hide from reader</button><button onclick={()=>reader(turn,false,null)}>Restore original reader text</button>{#if editing===turn.id}<textarea aria-label="Reader text" bind:value={draft}></textarea><button onclick={()=>reader(turn,false,draft)}>Save reader text</button>{/if}</details></div>{/if}
     </div>

    {:else}<div class="hidden-turn"><span>Hidden from reader</span><button onclick={()=>reader(turn,false,control(turn.id)?.text??null)}>Show in reader</button><button onclick={()=>reader(turn,false,null)}>Restore original reader text</button></div>{/if}
   </article>
  {/each}
 </div>
 {#if !nearBottom}<button class="latest" onclick={()=>{nearBottom=true;conversation?.scrollTo({top:conversation.scrollHeight,behavior:'smooth'});}}>↓ Latest message</button>{/if}
 <div class="compose-dock"><ActionInput {connected} {deliveryPending} {recoveredAction} {campaignId} {sessionId} thirdPerson={campaign?.preferences.thirdPerson||false} protagonistName={player?.name||'Player'} {run} {busy} {onturn} {onstop} {onresume} questionPending={pending}/></div>
</div>
<style>
 .story-reader{height:100%;min-height:0;display:flex;flex-direction:column;position:relative}.conversation-header{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:18px 24px;border-bottom:1px solid #303b30;flex-shrink:0}.conversation-header small{font:10px 'Segoe UI',sans-serif;letter-spacing:.12em;color:#b99b64}h1{font:22px/1.2 Georgia,serif;color:#efe7d8;margin:3px 0 4px}.conversation-header p{font:11px 'Segoe UI',sans-serif;color:#929d8b;margin:0}.conversation{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:24px max(20px,calc((100% - 760px)/2));scrollbar-color:#394633 transparent;scrollbar-width:thin}article{margin:0 0 30px}.message{max-width:100%;margin-bottom:18px}.player-message,.answer-message{max-width:84%;margin-left:auto;border:1px solid #40503b;border-radius:14px 14px 4px 14px;background:#253020;padding:12px 16px}.gm-message{padding:4px 0}.message-meta{display:flex;align-items:center;gap:9px;font:11px 'Segoe UI',sans-serif;color:#939d8b;margin-bottom:9px}.message-meta strong{font-weight:600;color:#c5cbbd}.message-meta>span:not(.gm-mark){text-transform:capitalize}.message-meta small{margin-left:auto;color:#c0aa7c}.gm-mark{border:1px solid #8e784e;color:#c6a66c;border-radius:5px;padding:1px 6px;font:15px Georgia,serif}.player,.answer-message p{font:14px/1.65 'Segoe UI',sans-serif;color:#e1e6d8;white-space:pre-wrap;margin:0;overflow-wrap:anywhere}.narration{font:var(--reading-font,17px)/1.8 Georgia,serif;color:#ece2cd;white-space:pre-wrap;margin:0 0 12px;overflow-wrap:anywhere}.thinking{display:flex;gap:4px;align-items:center;color:#9ea98f;min-height:35px}.thinking>span{height:5px;width:5px;border-radius:50%;background:#a4b38e;animation:pulse 1.2s infinite}.thinking>span:nth-child(2){animation-delay:.15s}.thinking>span:nth-child(3){animation-delay:.3s}.thinking p{font:12px 'Segoe UI',sans-serif;margin:0 0 0 8px}.turn-note,.draft-note{font:12px/1.5 'Segoe UI',sans-serif;color:#9ea98f}.draft-narration{opacity:.85}.turn-error-details{font:11px/1.5 "Segoe UI",sans-serif;color:#92998a;margin:8px 0}.turn-error-details summary{cursor:pointer}.turn-error{font:12px 'Segoe UI',sans-serif;color:#ecbec8;overflow-wrap:anywhere}.sources{display:flex;gap:9px;align-items:flex-start;flex-wrap:wrap;font:11px 'Segoe UI',sans-serif;color:#92998a}button{background:#192219;color:#c6a66c;border:1px solid #354035;border-radius:6px;padding:7px 10px;cursor:pointer;font:12px 'Segoe UI',sans-serif}button:hover{border-color:#a78c58}button:disabled{opacity:.45;cursor:default}.world-toggle{white-space:nowrap}.reader-controls{max-width:100%;flex:1}.reader-controls summary{cursor:pointer;padding:7px 0;color:#89947f}.reader-controls p{margin:9px 0;color:#92998a}.reader-controls button{margin:0 4px 6px 0}.reader-controls textarea{width:100%;box-sizing:border-box;min-height:100px;background:#101510;color:#eee3c9;border:1px solid #354035;border-radius:6px;padding:10px}.compose-dock{border-top:1px solid #354035;background:#151c14;padding:12px 20px 14px;flex-shrink:0}.question-card{background:#1a2318;border:1px solid #4b553b;border-radius:12px;padding:16px;margin-top:12px}.question-card h2{font:17px/1.4 Georgia,serif;margin:0 0 12px;color:#ece2cd}.answer-choices{display:flex;gap:8px;flex-wrap:wrap}.question-card label{display:block;font:11px 'Segoe UI',sans-serif;color:#adb79f;margin:14px 0 7px}.custom-answer{display:flex;gap:7px}.custom-answer input{min-width:0;flex:1;background:#101510;color:#eee3c9;border:1px solid #40503b;border-radius:6px;padding:8px}.dismiss{border:none;background:none;color:#92998a;margin-top:8px;padding-left:0}.roll-card{display:flex;gap:12px;align-items:center;font:12px 'Segoe UI',sans-serif;color:#c5cbbd;border:1px solid #354035;border-radius:8px;padding:9px;margin:12px 0}.roll-card strong{font:24px Georgia,serif;color:#c6a66c}.roll-card span{font-size:11px}.latest{position:absolute;right:22px;bottom:230px;background:#283521;box-shadow:0 4px 14px #0008}.welcome{max-width:430px;margin:8vh auto;text-align:center;color:#a3af97}.welcome-sigil{display:inline-block;font:36px Georgia,serif;color:#c6a66c;border:1px solid #8e784e;padding:4px 15px;border-radius:10px}.welcome h2{font:25px Georgia,serif;color:#ece2cd;margin:20px 0 10px}.welcome p{font:13px/1.7 'Segoe UI',sans-serif}.welcome .sources{justify-content:center;margin-top:20px}.hidden-turn{display:flex;gap:10px;align-items:center;border:1px dashed #354035;border-radius:8px;padding:12px;font:11px 'Segoe UI',sans-serif;color:#92998a}@keyframes pulse{0%,70%,100%{opacity:.3}35%{opacity:1}}@media(prefers-reduced-motion:reduce){.thinking>span{animation:none}}@media(max-width:650px){.conversation-header{padding:12px 14px}h1{font-size:18px}.conversation-header p{font-size:10px}.conversation{padding:18px 14px}.compose-dock{padding:10px 12px 12px}.player-message,.answer-message{max-width:90%;padding:10px 12px}.narration{font-size:16px}.custom-answer{flex-wrap:wrap}.custom-answer input{width:100%}.question-card{padding:12px}.question-card h2{font-size:16px}.latest{bottom:207px;right:14px}.sources{gap:6px}.welcome{margin:6vh auto}.hidden-turn{flex-wrap:wrap}}

 .story-reader{position:relative;min-width:0}.conversation{overflow-wrap:anywhere;overflow-anchor:auto;-webkit-overflow-scrolling:touch;overscroll-behavior-y:contain}.conversation article{scroll-margin-bottom:12px}.compose-dock{padding-bottom:max(14px,env(safe-area-inset-bottom,0px));box-sizing:border-box}.latest{bottom:auto;top:65px;min-height:44px;z-index:2}
 @media(max-width:1099px){.conversation-header{padding:9px 13px;gap:10px;flex-shrink:0}.conversation-header h1{font-size:18px;margin:2px 0 4px}.conversation-header small{display:none}.conversation-header p{font-size:11px;margin:0}.conversation-header button{min-height:44px;max-width:100px;font-size:12px;padding:6px 10px}.conversation{padding:15px 14px}.compose-dock{padding:9px 12px max(10px,env(safe-area-inset-bottom,0px))}.message-meta{flex-wrap:wrap}.narration{line-height:1.65}.sources button,.answer-choices button,.custom-answer button,.reader-controls button,.reader-controls summary{min-height:44px}.custom-answer input,.reader-controls textarea{font-size:16px}.player-message,.answer-message{max-width:94%}.question-card{padding:12px}.latest{right:12px;top:64px;font-size:12px}}
 @media(max-height:520px) and (max-width:1099px){.conversation-header{padding:4px 12px}.conversation-header p{display:none}.conversation-header h1{font-size:16px}.conversation{padding:10px 13px}.compose-dock{padding-top:5px}.latest{top:50px}}

</style>
